//! qrdrop's protocol, sans-IO.
//!
//! A port of `src/core/`, minus beam (web-only) and the file sources (IO).
//! Every value that crosses the wire is checked against `test/vectors/`,
//! which `scripts/make-vectors.mjs` writes from the real JS core and
//! `test/vectors.test.mjs` holds to it, so this crate and the website cannot
//! drift apart without a test failing on one side or the other.
//!
//! The order a pairing goes in, and the types that hold it:
//!
//! 1. [`Secret`]: generated by the host, or decoded from a scanned code.
//!    [`Secret::topic`] and [`Secret::password`] go to the room.
//! 2. [`Keypair`], one per strategy join, consumed by
//!    [`Keypair::establish`] with the peer's public key into a [`Pairing`].
//! 3. [`Pairing::sas`] is shown; [`Pairing::confirm`] is the person saying it
//!    matched, and is the only way to a [`Session`].
//! 4. The [`Session`] runs both directions of the transfer: frames in through
//!    [`Session::handle_frame`], frames out through [`Session::poll_transmit`],
//!    and everything the driver must act on through [`Session::poll_event`].
//!
//! No IO, no clock but the `Instant`s it is handed, no async, no threads.

#![forbid(unsafe_code)]

mod code;
mod control;
mod digest;
mod frame;
mod pairing;
mod transfer;
#[cfg(test)]
mod vectors;

pub use code::{CodeError, SECRET_BYTES, Secret};
